  window.LESSONS["u2_l08"] = {"meta":{"grade":5,"subject":"수학","term":2,"unit":2,"unit_title":"분수의 곱셈","n":8,"title":"와글와글 함께하는 공간 만들기","std":"분수의 곱셈 — (분수)×(자연수), (자연수)×(분수), (분수)×(분수)의 계산 원리를 이해하고 계산할 수 있으며 생활 문제에 활용할 수 있다 (성취기준 번호 확인 필요)","duration_min":40,"lesson_format":"활용 차시 · 2세대 19장(7요소)","theme":"생활 속 분수만큼","live_url":"../../grade5/semester2/math/2단원_분수의곱셈/g5_math_u2_l08_와글와글함께하는공간만들기.html","source":"grade5/semester2/math/2단원_분수의곱셈/g5_math_u2_l08_와글와글함께하는공간만들기.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"와글와글 함께하는 공간 만들기\n전체의 몇 분의 몇 이상","emoji":"🏛️"},"suggested_extras":["v_l8_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 대분수와 세 분수의 곱셈까지 **한 규칙**으로 계산했어요. 오늘은 배운 곱셈으로 **마을 문제**를 풀어 봐요.","items":[{"q":"1 1/4 × 1 1/5 을 계산했을 때 자연수 부분은 얼마일까요?","a":"1"},{"q":"3 × 1/4 × 2/3 을 기약분수로 나타냈을 때 분모는 얼마일까요?","a":"2"},{"q":"자연수 4를 분모가 1인 분수로 나타내면 분자는 얼마일까요?","a":"4"}],"from":"u2_l07"},"suggested_extras":["q_l8_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"마을 회관 동의 게시판","desc":"마을 회관 게시판에 「공공 도서관 만들기 — **전체 주민의 2/3 이상** 동의 필요」라는 안내문이 붙어 있어요. 아래 동의 칸에는 지금까지 **158명**이 이름을 적었어요.","question":"도서관을 만들려면 적어도 몇 명이 더 동의해야 할까요? 이 안내문만으로 구할 수 있을까요?","img":"assets/photo/math/village_library_vote.jpg","tnote":{"ask":["지금 알고 있는 수는 무엇인가요?","빠진 정보는 무엇일까요?"],"watch":"158 × 2/3 을 계산하려는 경우","min":3}},"suggested_extras":["q_l8_2","r_l8_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"fch","items":["2/3"],"note":"서연이네 마을 — 전체 주민의 2/3 이상이 동의해야 한다"},"title":"구하려는 것과 알고 있는 것","content":"**구하려는 것** — 적어도 몇 명이 더 동의해야 하는가.\n**알고 있는 것** — 전체 주민의 2/3 이상이어야 하고, 지금까지 158명이 동의했다.\n이대로는 풀 수 없다.\n무엇이 더 있어야 할까?","tnote":{"ask":["구하려는 것은 무엇인가요?","알고 있는 것만으로 풀 수 있나요?"],"watch":"알고 있는 수만으로 곱하려는 경우","min":4}},"suggested_extras":["e_l8_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"opb","whole":270,"n":2,"d":3,"res":"180","cap":"270명을 똑같이 3으로 나눈 것 중의 2"},"title":"적어도 몇 명이 동의해야 할까","content":"전체 주민 270명의 2/3 이상이 동의해야 한다.\n270 × 2/3 = **180(명)** 이다.\n적어도 180명이 동의해야 공공 도서관을 만들 수 있다.","tnote":{"ask":["270의 2/3 는 어떻게 구했나요?","180명은 무엇을 뜻하나요?"],"watch":"270 × 2 만 하는 경우","min":4}},"suggested_extras":["t_l8_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"mcc","rows":[{"lead":"필요한 수","expr":"270 × 2/3 = 180"},{"lead":"더 필요","expr":"180 - 158 = 22"}]},"title":"몇 명이 더 동의해야 할까","content":"지금까지 158명이 동의했다.\n180 − 158 = **22(명)** 이다.\n적어도 22명이 더 동의해야 한다.","tnote":{"ask":["더 필요한 사람 수는 어떻게 구했나요?","왜 빼기를 했나요?"],"watch":"180을 답으로 하는 경우","min":4}},"suggested_extras":["e_l8_2","t_l8_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"mcc","rows":[{"lead":"필요한 수","expr":"430 × 3/5 = 258"},{"lead":"더 필요","expr":"258 - 195 = 63"}]},"title":"준기네 마을은 어떨까","content":"준기네 마을은 **전체 주민의 3/5 이상**이 동의해야 하고 전체 주민은 **430명**이다.\n430 × 3/5 = **258(명)** 이 동의해야 하는데 지금까지 195명이 동의했다.\n258 − 195 = **63(명)** 이 더 동의해야 한다.","tnote":{"ask":["준기네 마을의 기준은 무엇인가요?","두 마을을 푼 차례는 같았나요?"],"watch":"두 마을의 기준 분수를 바꾸어 쓰는 경우","min":4}},"suggested_extras":["q_l8_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"「2/3 이상」이니 지금 동의한 **158명에 2/3 을 곱하면** 된다.","right":"2/3 은 **전체 주민**의 2/3 이에요. 먼저 전체 주민 수를 알아야 해요. 270 × 2/3 = **180**(명)이 필요하고, 180 − 158 = **22**(명)이 더 동의해야 해요.","hint":"「누구의 2/3 인가?」를 칠판에 쓰고, 분수 앞의 「전체」에 동그라미를 치게 하세요.","tnote":{"ask":["2/3 은 누구의 2/3 인가요?","158명은 무엇과 견주어야 하나요?"],"watch":"기준이 되는 전체를 바꾸는 경우","min":3}},"suggested_extras":["x_l8_1","x_l8_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🔢","body":"안내문에 빠진 정보를 찾아요."},"question":"문제를 풀기 위해 **더 알아야 하는 것**은 무엇일까요?","fig":{"k":"fch","items":["2/3"],"note":"전체 주민 수를 모른다"},"options":[{"text":"전체 주민 수","correct":true},{"text":"동의한 사람의 이름"},{"text":"마을의 넓이"},{"text":"도서관의 크기"}],"note":"풀이: 「전체의 2/3」에서 **전체**가 무엇인지 생각해 보자. 곱해야 할 수가 빠져 있다. → **전체 주민 수**"},"suggested_extras":["t_l8_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🔢","body":"전체 주민 수를 알았어요."},"question":"서연이네 마을 전체 주민은 **270명**이에요. 적어도 몇 명이 동의해야 할까요?","fig":{"k":"opb","whole":270,"n":2,"d":3,"ask":true},"input":"count_input","answer":180,"note":"풀이: 270을 똑같이 3으로 나누어 보자. 한 묶음이 90이다. → **180**"},"suggested_extras":["e_l8_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🔢","body":"준기네 마을도 살펴봐요."},"question":"준기네 마을에서 지금까지 **195명**이 동의했어요. 적어도 몇 명이 **더** 동의해야 할까요?","fig":{"k":"fch","items":["3/5"],"note":"지금까지 195명이 동의했다"},"input":"count_input","answer":63,"note":"풀이: 258명이 동의해야 한다. 258 − 195 를 계산한다. → **63**"},"suggested_extras":["q_l8_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"전체 주민 120명의 3/4 이상이 동의해야 한다면 적어도 몇 명이 동의해야 할까요?","a":"90","steps":["120을 똑같이 4로 나누면 30","그 중의 3","30 × 3 = 90"]},"도전":{"q":"전체 주민 350명의 4/7 이상이 동의해야 하고 지금까지 150명이 동의했어요. 적어도 몇 명이 더 동의해야 할까요?","a":"50","steps":["350 × 4/7 = 200","200 − 150 = 50","50명"]},"심화":{"q":"우리 학교에 만들고 싶은 공간을 정하고, 「전체 학생의 몇 분의 몇 이상 동의」 규칙을 정해 필요한 학생 수를 구해 봐요.","a":"여러 답 (예: 전체 학생 240명의 3/5 이상 → 240 × 3/5 = 144명)","open":true}},"tnote":{"ask":["기본에서 전체는 몇 명인가요?","심화에서 정한 규칙의 전체는 무엇인가요?"],"watch":"도전에서 200명을 답으로 하는 경우","min":5}},"suggested_extras":["q_l8_5","g_l8_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"우리 반 공간 투표","type":"group","goal":"모둠이 우리 반에 만들고 싶은 공간을 하나씩 제안하고, 「우리 반 전체의 2/3 이상」 규칙으로 필요한 표 수를 구해 모은 표와 견주기","steps":["모둠마다 만들고 싶은 공간(책 쉼터·놀이 구석 등)을 하나 정해 제안 카드를 쓴다","우리 반 전체 학생 수 × 2/3 로 필요한 표 수를 구한다","반 전체가 붙임쪽지로 투표한다","모은 표와 필요한 표를 견주어 몇 표가 더 필요한지 말한다"],"solo":["만들고 싶은 공간 하나를 정한다","전체 학생 수를 정하고 2/3 이상에 필요한 수를 구한다","지금 찬성한 수를 정해 몇 명이 더 필요한지 쓴다"],"materials":["제안 카드","붙임쪽지","투표판"],"minutes":10,"tnote":{"ask":["필요한 표 수는 어떻게 구했나요?","전체 학생 수가 3으로 나누어떨어지지 않으면 어떻게 할까요?"],"watch":"모은 표에 2/3 을 곱하는 모둠","min":10}},"suggested_extras":["g_l8_2","t_l8_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"아파트 주민 투표","scenario":{"icon":"🏢","body":"아파트에서 놀이터를 고칠 때 전체 세대의 몇 분의 몇 이상이 찬성해야 정하는 경우가 있어요."},"content":"「**전체의 몇 분의 몇**」은 곱셈 상황이에요. 문제에 없는 정보를 먼저 찾고, 필요한 수를 구한 뒤 이미 있는 수를 빼요."},"suggested_extras":["r_l8_2","r_l8_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"어느 마을 전체 주민은 540명이고 5/9 이상이 동의해야 해요. 지금까지 동의한 주민은 전체 주민의 1/3 이에요.","challenge":"적어도 몇 명이 더 동의해야 할까요?","note":"풀이: 540 × 5/9 = 300 · 540 × 1/3 = 180 · 300 − 180 = **120**(명)","tnote":{"ask":["필요한 사람 수는?","지금까지 동의한 사람 수는?"],"watch":"5/9 − 1/3 을 먼저 하고 멈추는 경우","min":4}},"suggested_extras":["t_l8_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"전체 주민 180명의 2/3 는 몇 명일까요?","a":"120"},{"q":"90명이 동의해야 하는데 지금까지 74명이 동의했어요. 몇 명이 더 동의해야 할까요?","a":"16"},{"q":"「전체의 몇 분의 몇」을 구할 때 쓰는 셈은 무엇일까요?","a":"곱셈"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["「전체의 몇 분의 몇」은 **곱셈** 상황이다.","문제에 없는 정보를 먼저 찾아내고, 필요한 수를 구한 뒤 이미 있는 수를 뺀다.","도서관 안내문에는 전체 주민 수가 빠져 있었고, 270명을 알고 나서야 22명이 더 필요하다는 것을 구했다."],"arrows":["빠진 정보 찾기","전체 × 분수 = 필요한 수","필요한 수 − 이미 있는 수"]},"suggested_extras":["r_l8_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 「전체의 몇 분의 몇」 문제를 푸는 차례를 말할 수 있나요?","🔧 과정·기능 — 필요한 수와 더 필요한 수를 구할 수 있나요?","💛 가치·태도 — 우리 반 공간을 함께 정하는 데 참여했나요?"],"prompts":["오늘 문제에서 빠진 정보를 어떻게 알아차렸나요?"]},"suggested_extras":["e_l8_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"스스로 마무리해요. 오늘 배운 것을 집에서 한 번 더 떠올려 보자.","emoji":"🏁"},"suggested_extras":["c_l8_1"]}],"extras":[{"id":"v_l8_1","type":"video","icon":"🎥","title":"분수의 곱셈 활용 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+5%ED%95%99%EB%85%84+%EB%B6%84%EC%88%98%EC%9D%98+%EA%B3%B1%EC%85%88+%ED%99%9C%EC%9A%A9+%EB%AC%B8%EC%A0%9C","description":"전체의 몇 분의 몇을 구하는 생활 문제 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l8_1","type":"fun_question","icon":"💡","title":"빠진 정보","content":"안내문만으로 풀 수 있을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_2","type":"fun_question","icon":"💡","title":"누구의 2/3","content":"2/3 은 누구의 2/3 일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_3","type":"fun_question","icon":"💡","title":"필요한 수","content":"270의 2/3 는 몇 명일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_4","type":"fun_question","icon":"💡","title":"더 필요","content":"더 필요한 사람 수는 어떻게 구할까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_5","type":"fun_question","icon":"💡","title":"두 마을","content":"어느 마을이 더 많이 필요할까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l8_1","type":"tip","icon":"🧩","title":"구하려는 것","content":"구하려는 것과 알고 있는 것을 두 칸에 나누어 쓰게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_2","type":"tip","icon":"🧩","title":"전체에 동그라미","content":"분수 앞의 「전체」에 동그라미를 치게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_3","type":"tip","icon":"🧩","title":"차례 번호","content":"① 필요한 수 ② 더 필요한 수 차례를 붙이게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_4","type":"tip","icon":"🧩","title":"나누어떨어짐","content":"반 인원이 나누어떨어지지 않으면 「적어도」의 뜻으로 올려 세게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_5","type":"tip","icon":"🧩","title":"투표판 사진","content":"모은 표를 사진으로 남겨 다음 시간에 쓰세요.","fit_slides":["concept","misconception"]},{"id":"r_l8_1","type":"real_world","icon":"🌍","title":"아파트 투표","content":"전체 세대의 몇 분의 몇 이상.","fit_slides":["real_world","summary"]},{"id":"r_l8_2","type":"real_world","icon":"🌍","title":"학생회","content":"전체 학생의 몇 분의 몇 찬성.","fit_slides":["real_world","summary"]},{"id":"r_l8_3","type":"real_world","icon":"🌍","title":"마을 회관","content":"주민 동의로 공간 만들기.","fit_slides":["real_world","summary"]},{"id":"g_l8_1","type":"game","icon":"🎮","title":"필요한 표 맞히기","content":"전체와 분수를 듣고 필요한 수 말하기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l8_2","type":"game","icon":"🎮","title":"빠진 정보 찾기","content":"문제 카드에서 빠진 정보 찾기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l8_1","type":"misconception","icon":"⚠️","title":"이미 있는 수에 곱하기","content":"동의한 수에 분수를 곱하는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l8_2","type":"misconception","icon":"⚠️","title":"빼기 빠뜨림","content":"필요한 수만 구하고 멈추는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l8_1","type":"example","icon":"📝","title":"게시판 그림","content":"마을 회관 동의 게시판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_2","type":"example","icon":"📝","title":"연산자 띠","content":"270을 셋으로 나눈 띠를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_3","type":"example","icon":"📝","title":"두 마을 표","content":"서연이네·준기네 기준 표를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l8_1","type":"checklist","icon":"✅","title":"다음 시간 준비","content":"이 단원에서 가장 헷갈린 곱셈 하나를 적어 옵니다.","fit_slides":["next_lesson"]}]};
  window.LESSONS["u2_l09"] = {"meta":{"grade":5,"subject":"수학","term":2,"unit":2,"unit_title":"분수의 곱셈","n":9,"title":"스스로 마무리해요 (단원 정리)","std":"분수의 곱셈 — (분수)×(자연수), (자연수)×(분수), (분수)×(분수)의 계산 원리를 이해하고 계산할 수 있으며 생활 문제에 활용할 수 있다 (성취기준 번호 확인 필요)","duration_min":40,"lesson_format":"단원 정리 · 2세대 19장(7요소)","theme":"생활 속 분수만큼","live_url":"../../grade5/semester2/math/2단원_분수의곱셈/g5_math_u2_l09_스스로마무리해요.html","source":"grade5/semester2/math/2단원_분수의곱셈/g5_math_u2_l09_스스로마무리해요.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"스스로 마무리해요\n분수의 곱셈 정리","emoji":"🏁"},"suggested_extras":["v_l9_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 분수의 곱셈으로 **마을 문제**를 풀었어요. 오늘은 단원 전체를 **스스로 정리**해 봐요.","items":[{"q":"전체 주민 180명의 2/3 는 몇 명일까요?","a":"120"},{"q":"90명이 동의해야 하는데 지금까지 74명이 동의했어요. 몇 명이 더 동의해야 할까요?","a":"16"},{"q":"「전체의 몇 분의 몇」을 구할 때 쓰는 셈은 무엇일까요?","a":"곱셈"}],"from":"u2_l08"},"suggested_extras":["q_l9_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"단원 정리 게시판","desc":"교실 뒤 게시판에 이 단원에서 만난 장면들이 붙어 있어요. 응원 현수막, 사과주스 병, 흙덩이, 텃밭, 시루떡, 밀가루 저울, 마을 게시판.","question":"게시판의 장면들을 **같은 수를 여러 번 더한 것**과 **전체의 얼마만큼을 구한 것**으로 나누면 어떻게 나뉠까요?","img":"assets/photo/math/fraction_review_board.jpg","tnote":{"ask":["여러 번 더한 장면은 무엇인가요?","얼마만큼을 구한 장면은 무엇인가요?"],"watch":"두 뜻을 구별하지 않고 모두 같다고 하는 경우","min":3}},"suggested_extras":["q_l9_2","r_l9_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"mcc","rows":[{"lead":"되짚기","expr":"1/3 × 4 = 4/3"},{"lead":"대분수","expr":"= 1 1/3"}]},"title":"(분수)×(자연수) 되짚기","content":"1/3 × 4 = 4/3 = 1 1/3 이다.\n수직선에서 1/3 씩 네 번 뛰어 센 것과 같다.\n한 칸의 크기는 그대로이고 칸의 개수만 늘어났다.","tnote":{"ask":["1/3 × 4 는 수직선에서 어떻게 보이나요?","분모는 바뀌었나요?"],"watch":"분모에 4를 곱하는 경우","min":4}},"suggested_extras":["e_l9_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"opb","whole":8,"n":3,"d":4,"res":"6","cap":"8을 똑같이 4로 나눈 것 중의 3"},"title":"(자연수)×(분수) 되짚기","content":"8 × 3/4 은 8을 똑같이 4로 나눈 것 중의 3이다.\n한 묶음이 2이므로 세 묶음은 **6** 이다.\n같은 수를 여러 번 더한 것이 아니라 **전체의 얼마**인지를 구했다.","tnote":{"ask":["8을 몇 묶음으로 나누었나요?","8 × 3/4 은 8보다 큰가요?"],"watch":"곱했으니 커졌다고 여기는 경우","min":4}},"suggested_extras":["t_l9_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"agr","an":2,"ad":3,"bn":1,"bd":5,"cap":"2/3 × 1/5 = 2/15"},"title":"(분수)×(분수) 되짚기","content":"2/3 × 1/5 은 전체를 3×5 = 15칸으로 나눈 것 중 2×1 = 2칸이다.\n따라서 **2/15** 다.\n칸을 세던 것이 그대로 계산 방법이 되었다.","tnote":{"ask":["전체 칸과 빗금 칸은 각각 몇 칸인가요?","분모끼리·분자끼리 곱한 값과 같나요?"],"watch":"분모끼리 더하는 경우","min":4}},"suggested_extras":["e_l9_2","t_l9_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"cmm","base":8,"items":[{"v":"3/4"},{"v":"1 1/4"}],"note":"곱하는 수가 1보다 작으면 값은 작아진다"},"title":"왜 그럴까 — 곱하면 커진다는 믿음을 마지막으로","content":"8 × 3/4 = 6 이다.\n곱했는데 8보다 **작아졌다**.\n곱하는 수 3/4 이 1보다 작기 때문이다.\n곱셈은 커지는 계산이 아니라 **곱하는 수만큼**을 구하는 계산이다.","tnote":{"ask":["곱했는데 왜 작아졌나요?","1 1/4 을 곱하면 어떻게 될까요?"],"watch":"곱셈은 늘 커진다고 다시 말하는 경우","min":4}},"suggested_extras":["q_l9_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"대분수가 있는 곱셈도 **바로 약분**해서 계산해도 된다 — 3 2/5 × 5/8 은 5끼리 약분해 3 × 1/4.","right":"대분수 3 2/5 는 3 + 2/5 예요. 먼저 **17/5** 로 고친 뒤 약분하면 17/5 × 5/8 = **17/8 = 2 1/8** 이에요.","hint":"3 2/5 × 5/8 을 두 줄로 계산하게 하고, 자연수 부분 3이 어떻게 되었는지 동그라미로 찾게 하세요.","tnote":{"ask":["두 줄의 값은 같았나요?","대분수는 먼저 무엇으로 고치나요?"],"watch":"분수 부분만 약분하는 경우","min":3}},"suggested_extras":["x_l9_1","x_l9_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🔢","body":"대분수에 자연수를 곱해요."},"question":"5 × 1 2/9 을 **대분수**로 나타내면 무엇일까요?","fig":{"k":"fch","items":["1 2/9"],"note":"5배를 구한다"},"options":[{"text":"6 1/9","correct":true},{"text":"6 2/9"},{"text":"5 2/9"},{"text":"7 1/9"}],"note":"풀이: 1 2/9 = 11/9 이다. 5 × 11 = 55 이고 55 ÷ 9 를 해 보자. → **6 1/9**"},"suggested_extras":["t_l9_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🔢","body":"두 분수를 곱해요."},"question":"2/3 × 9/14 를 기약분수로 나타내면 무엇일까요?","fig":{"k":"fch","items":["2/3","9/14"]},"options":[{"text":"2/7"},{"text":"9/42"},{"text":"3/7","correct":true},{"text":"1/7"}],"note":"풀이: 2 × 9 = 18, 3 × 14 = 42 이다. 18과 42를 6으로 나누어 보자. → **3/7**"},"suggested_extras":["e_l9_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🔢","body":"하루를 똑같이 나누어요."},"question":"지한이는 토요일 **하루의 1/8** 동안 책을 읽었어요. 몇 시간 읽었을까요?","fig":{"k":"opb","whole":24,"n":1,"d":8,"ask":true,"cap":"하루를 똑같이 8로 나눈 것 중의 1"},"input":"count_input","answer":3,"note":"풀이: 하루는 24시간이다. 24를 똑같이 8로 나누어 보자. → **3**"},"suggested_extras":["q_l9_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"3/8 × 4 를 기약분수로 나타냈을 때 분모는 얼마일까요?","a":"2","steps":["3 × 4 = 12 → 12/8","12와 8을 4로 나누어요","3/2 → 분모 2"]},"도전":{"q":"1 3/4 × 2 2/7 은 얼마일까요?","a":"4","steps":["7/4 × 16/7","= 112/28","= 4"]},"심화":{"q":"이 단원의 곱셈 네 가지((분수)×(자연수)·(자연수)×(분수)·(분수)×(분수)·세 수의 곱셈)를 한 장의 생각 그물로 정리하고 예를 하나씩 써 봐요.","a":"여러 답 (예: 2/5 × 3 = 6/5 · 6 × 2/3 = 4 · 1/2 × 3/4 = 3/8 · 1/2 × 2/3 × 3/4 = 1/4)","open":true}},"tnote":{"ask":["기본에서 어떻게 약분했나요?","심화에서 가장 헷갈린 곱셈은 무엇이었나요?"],"watch":"도전에서 대분수를 그대로 곱하는 경우","min":5}},"suggested_extras":["q_l9_5","g_l9_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"분수 곱셈 퀴즈 열쇠","type":"group","goal":"모둠이 네 가지 곱셈 퀴즈 카드를 번갈아 풀어 열쇠를 모으고, 틀린 카드는 까닭을 찾아 고친 뒤 생각 그물을 완성하기","steps":["모둠마다 네 가지 곱셈 퀴즈 카드와 열쇠 스티커를 받는다","한 사람씩 카드를 풀고 다른 사람이 확인한다","틀린 카드는 가분수·약분·분모끼리를 근거로 고친 뒤 열쇠를 받는다","모은 열쇠로 생각 그물의 빈칸을 채우고 발표한다"],"solo":["퀴즈 카드 여섯 장을 차례로 푼다","답을 확인하고 틀린 것은 까닭을 쓴다","생각 그물 한 장으로 단원을 정리한다"],"materials":["곱셈 퀴즈 카드","열쇠 스티커","생각 그물 틀"],"minutes":8,"tnote":{"ask":["가장 많이 틀린 카드는 무엇이었나요?","틀린 까닭을 어떻게 찾았나요?"],"watch":"답만 맞히고 까닭은 넘어가는 모둠","min":8}},"suggested_extras":["g_l9_2","t_l9_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"생활 속 분수의 곱셈","scenario":{"icon":"🗺️","body":"레시피 늘리기, 시간 나누기, 땅 넓이, 마을 투표 — 우리 생활 곳곳에서 분수의 곱셈을 써요."},"content":"분수의 곱셈은 **가분수로 고쳐 분모끼리·분자끼리 곱한다**는 한 규칙으로 모여요. 곱하는 수가 **1보다 작으면** 값은 작아져요."},"suggested_extras":["r_l9_2","r_l9_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"어느 날 하루의 1/3 은 잠을 잤고, 깨어 있던 시간의 3/8 은 학교에서 보냈어요.","challenge":"학교에서 보낸 시간은 몇 시간일까요?","note":"풀이: 24 × 1/3 = 8 · 깨어 있던 시간 24 − 8 = 16 · 16 × 3/8 = **6**(시간)","tnote":{"ask":["깨어 있던 시간은 몇 시간인가요?","3/8 은 무엇의 3/8 인가요?"],"watch":"24 × 3/8 로 계산하는 경우","min":4}},"suggested_extras":["t_l9_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"2/5 × 10 은 얼마일까요?","a":"4"},{"q":"18 × 5/6 은 얼마일까요?","a":"15"},{"q":"1/3 × 3/7 을 기약분수로 나타냈을 때 분모는 얼마일까요?","a":"7"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["분수의 곱셈은 **가분수로 고쳐 분모끼리·분자끼리 곱한다**는 한 규칙으로 모인다.","곱하는 수가 1보다 작으면 값은 작아진다.","게시판의 장면들은 「여러 번 더하기」와 「얼마만큼」으로 나뉘었지만, 계산은 모두 한 규칙으로 모였다."],"arrows":["여러 번 더하기 · 얼마만큼","가분수로 고쳐 분모끼리 · 분자끼리","곱하는 수 < 1 이면 작아짐"]},"suggested_extras":["r_l9_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 분수의 곱셈 네 가지를 말할 수 있나요?","🔧 과정·기능 — 대분수가 있어도 바르게 계산할 수 있나요?","💛 가치·태도 — 헷갈린 것을 스스로 찾아 고치려 했나요?"],"prompts":["이 단원에서 가장 헷갈렸던 것과 지금 이해한 것은?"]},"suggested_extras":["e_l9_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 단원엔","preview":"분수의 곱셈 단원을 마쳤어요! 다음 단원에서는 **합동과 대칭**을 배워요. 똑같이 생긴 두 물건이나 반으로 접으면 꼭 겹치는 모양을 하나 찾아 와요.","emoji":"🪞"},"suggested_extras":["c_l9_1"]}],"extras":[{"id":"v_l9_1","type":"video","icon":"🎥","title":"단원 정리 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+5%ED%95%99%EB%85%84+%EB%B6%84%EC%88%98%EC%9D%98+%EA%B3%B1%EC%85%88+%EB%8B%A8%EC%9B%90+%EC%A0%95%EB%A6%AC","description":"단원 핵심을 한 번에 되짚는 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l9_1","type":"fun_question","icon":"💡","title":"두 뜻","content":"여러 번 더하기와 얼마만큼은 무엇이 다를까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_2","type":"fun_question","icon":"💡","title":"한 규칙","content":"분수의 곱셈은 어떤 한 규칙으로 모일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_3","type":"fun_question","icon":"💡","title":"작아짐","content":"8 × 3/4 은 왜 8보다 작을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_4","type":"fun_question","icon":"💡","title":"대분수","content":"대분수가 있으면 먼저 무엇을 할까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_5","type":"fun_question","icon":"💡","title":"생활","content":"이 단원에서 배운 것을 어디서 쓸 수 있을까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l9_1","type":"tip","icon":"🧩","title":"생각 그물","content":"네 가지 곱셈으로 생각 그물 틀을 나누어 주세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_2","type":"tip","icon":"🧩","title":"퀴즈 카드","content":"퀴즈 카드에 까닭 쓰는 칸을 두세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_3","type":"tip","icon":"🧩","title":"짝 확인","content":"서로 답을 확인하고 까닭을 말하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_4","type":"tip","icon":"🧩","title":"모둠 발표","content":"가장 헷갈린 것을 모둠마다 하나씩 발표하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_5","type":"tip","icon":"🧩","title":"되짚기","content":"단원 내내 쓴 세 칸 표를 다시 정리하세요.","fit_slides":["concept","misconception"]},{"id":"r_l9_1","type":"real_world","icon":"🌍","title":"레시피","content":"재료를 몇 배로 늘리기.","fit_slides":["real_world","summary"]},{"id":"r_l9_2","type":"real_world","icon":"🌍","title":"시간","content":"하루의 몇 분의 몇.","fit_slides":["real_world","summary"]},{"id":"r_l9_3","type":"real_world","icon":"🌍","title":"투표","content":"전체의 몇 분의 몇 이상.","fit_slides":["real_world","summary"]},{"id":"g_l9_1","type":"game","icon":"🎮","title":"곱셈 빙고","content":"분수 곱셈 값 빙고.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l9_2","type":"game","icon":"🎮","title":"퀴즈 열쇠","content":"퀴즈를 풀어 열쇠 모으기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l9_1","type":"misconception","icon":"⚠️","title":"바로 약분","content":"대분수를 바로 약분하는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l9_2","type":"misconception","icon":"⚠️","title":"늘 커진다","content":"곱하면 늘 커진다고 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l9_1","type":"example","icon":"📝","title":"네 곱셈 카드","content":"네 가지 곱셈 예 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l9_2","type":"example","icon":"📝","title":"넓이 모델","content":"2/3 × 1/5 칸 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l9_3","type":"example","icon":"📝","title":"크기 카드","content":"8 × 3/4 · 8 × 1 1/4 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l9_1","type":"checklist","icon":"✅","title":"다음 단원 준비","content":"똑같이 생긴 두 물건을 하나 찾아 옵니다.","fit_slides":["next_lesson"]}]};
